window.AUTH=window.AUTH||{};window.AUTH["22-1008"]={"d":"22-1008","id":"2023/22-1008","n":"Corner Post, Inc. v. Board of Governors of the Federal Reserve System","briefs":[{"k":"petitioner","label":"Brief of petitioner Corner Post, Inc.","date":"2023-11-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-1008/289472/20231113164723538_22-1008%20Corner%20Post%20opening%20merits%20brief%20Final.pdf","side":"pet","n":84},{"k":"respondent","label":"Brief of respondent Board of Governors of the Federal Reserve Sytem","date":"2023-12-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-1008/293318/20231213165432435_22-1008bsUnitedStates.pdf","side":"res","n":113},{"k":"reply","label":"Reply of petitioner Corner Post, Inc.","date":"2024-01-12","url":"https://www.supremecourt.gov/DocketPDF/22/22-1008/295695/20240112160022813_22-1008%20Merit%20Reply%20Brief%20Final.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r59_4fci.pdf","tr":true,"items":[{"t":"case","label":"Abbott Lab’ys v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"op":11,"ar":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"0":"12, 30, 40","1":"12","2":"16, 18"}},{"t":"case","label":"Armstrong v. Bush","cite":"924 F.2d 282","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/924/282/","by":{"0":"41"}},{"t":"case","label":"Bay Area Laundry & Dry Cleaning Pension Tr. Fund v. Ferbar Corp.","cite":"522 U.S. 192","y":1997,"id":"1997/96-370","sc":1,"op":8,"sum":"The Court held that the MPPAA's six-year statute of limitations on a pension fund's action to collect unpaid withdrawal liability does not begin to run until the employer fails to make a payment on the schedule set by the fund.","sumSrc":"Oyez","by":{"0":"3, 15, 16, 18, 23, 28","1":"26, 28","2":"4, 7, 8, 12"}},{"t":"case","label":"Booth v. United States","cite":"914 F.3d 1199","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/914/1199/","by":{"0":"23"}},{"t":"case","label":"Bowen v. Mich. Acad. of Fam. Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Cal. Pub. Emps.’ Ret. Sys. v. ANZ Sec. Inc.","cite":"582 U.S. 497","y":2017,"url":"https://supreme.justia.com/cases/federal/us/582/497/","sc":1,"by":{"0":"40"}},{"t":"case","label":"CIC Servs., LLC v. IRS","cite":"141 S. Ct. 1582","y":2021,"id":"2020/19-930","sc":1,"sum":"A suit to enjoin IRS Notice 2016–66 does not trigger the Anti-Injunction Act even though a violation of the Notice may result in a tax penalty.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"31, 35, 36"}},{"t":"case","label":"City of Almaty v. Ablyazov","cite":"2019 WL 1430155","by":{"0":"39"}},{"t":"case","label":"Crown Coat Front Co. v. United States","cite":"386 U.S. 503","y":1967,"id":"1966/371","sc":1,"op":18,"ar":8,"sum":"Recognizing “the hazards inherent in attempting to defne for all purposes when a `cause of action' frst `accrues' ”.","sumSrc":"opinion","by":{"0":"3, 17, 19, 20, 21, 23","1":"13, 14, 24-26, 28, 31","2":"7, 8, 10"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"op":5,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"0":"27, 28, 31","1":"33"}},{"t":"case","label":"DHS v. Regents of the Univ. of Cal.","cite":"140 S. Ct. 1891","y":2020,"id":"2019/18-587","sc":1,"op":2,"sum":"The Court held that the Department of Homeland Security’s decision to rescind the Deferred Action for Childhood Arrivals program was arbitrary and capricious under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Dir., Off. of Workers’ Comp. Programs, Dep’t of Lab. v. Newport News Shipbuilding & Dry Dock Co.","cite":"514 U.S. 122","y":1995,"id":"1994/93-1783","sc":1,"op":2,"sum":"The Director is not \"adversely affected or aggrieved\" under §921(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 11, 14, 18, 19","2":"12"}},{"t":"case","label":"Dodd v. United States","cite":"545 U.S. 353","y":2005,"id":"2004/04-5286","sc":1,"op":2,"sum":"The Court held that the text of the federal law \"unequivocally\" stated that the one-year limitation period begins to run on the date on which the Court \"initially recongized\" the right, not the date on which that right was made retroactive.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Doe v. Bolton","cite":"410 U.S. 179","y":1973,"id":"1971/70-40","sc":1,"sum":"Georgia law proscribes an abortion except as performed by a duly licensed Georgia physician when necessary in \"his best clinical judgment\" becausecontinued pregnancy would endanger a pregnant woman's life or injure her health; the fetus would likely be barn with a serious defect; or the pregnancy resulted from rape. § 26-1202 (a) of Ga. Criminal Code. In addition to a requirement that the patient be a Georgia …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Dunn-McCampbell Royalty Int., Inc. v. NPS","cite":"112 F.3d 1283","y":1997,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/112/1283/","op":2,"by":{"0":"21, 22, 33","1":"14, 41"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Franconia Assocs. v. United States","cite":"536 U.S. 129","y":2002,"id":"2001/01-455","sc":1,"op":1,"ar":2,"sum":"The Court held that because ELIHPA's enactment qualified as a repudiation of the parties' bargain, not a present breach of the loan agreements, breach would occur, and the six-year limitations period would commence to run, when a borrower tenders prepayment and the Government then dishonors its obligation to accept the tender and release its control over use of the property securing the loan.","sumSrc":"Oyez","by":{"0":"24","1":"32","2":"8, 9, 10"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Acct. Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"30, 35"}},{"t":"case","label":"Gabelli v. SEC","cite":"568 U.S. 442","y":2013,"id":"2012/11-1274","sc":1,"op":7,"ar":3,"sum":"The Court held that a five-year statute of limitations period begins at the time the violation is committed.","sumSrc":"Oyez","by":{"0":"2, 11, 15, 20","1":"26, 45","2":"3, 11"}},{"t":"case","label":"Graham Cnty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"545 U.S. 409","y":2005,"id":"2004/04-169","sc":1,"op":4,"sum":"The Court ruled that the six-year statute of limitations did not apply to suits for retaliation. The majority opinion by Justice Clarence Thomas found the statute of limitations \"ambiguous.\" The ambiguity arose from the fact that the six-year limitation in the FCA starts from the time the false claim was made. Yet in a retaliation suit, no actual false claim needs to be alleged.","sumSrc":"Oyez","by":{"0":"3, 14, 16, 17, 24","1":"20, 26, 28","2":"7, 8"}},{"t":"case","label":"Herr v. U.S. Forest Serv.","cite":"803 F.3d 809","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/803/809/","op":6,"ar":5,"by":{"0":"2, 10, 18, 21, 22, 38","1":"7, 19","2":"3, 13, 17"}},{"t":"case","label":"Hire Ord. Ltd. v. Marianos","cite":"698 F.3d 168","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/698/168/","op":2,"by":{"0":"21, 22","1":"13"}},{"t":"case","label":"Johnson v. United States","cite":"544 U.S. 295","y":2005,"id":"2004/03-9685","sc":1,"sum":"The Court held that by waiting until more than three years after his federal sentence, Johnson failed to show due diligence in seeking to have his original state convictions vacated.","sumSrc":"Oyez","by":{"0":"16","1":"26, 28","2":"8"}},{"t":"case","label":"Jud. Watch, Inc. v. Kerry","cite":"844 F.3d 952","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/844/952/","by":{"0":"41"}},{"t":"case","label":"Kannikal v. Att’y Gen.","cite":"776 F.3d 146","y":2015,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/776/146/","by":{"0":"4"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"35, 39","1":"43","2":"22"}},{"t":"case","label":"Macklin v. United States","cite":"300 F.3d 814","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/300/814/","by":{"0":"23"}},{"t":"case","label":"Match-E-Be-Nash-She-Wish Band of Pottawatomi Indians v. Patchak","cite":"567 U.S. 209","y":2012,"id":"2011/11-246","sc":1,"sum":"The Court held that a neighbor of a proposed Indian casino had standing to sue the government for taking 147 acres of a town's land under Section 465 of the Indian Reorganization Act.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"MedImmune, Inc. v. Genentech, Inc.","cite":"549 U.S. 118","y":2007,"id":"2006/05-608","sc":1,"op":2,"sum":"The Court reversed the Federal Circuit and ruled for MedImmune.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"NACS v. Bd. of Governors of the Fed. Rsrv. Sys.","cite":"746 F.3d 474","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/746/474/","op":2,"by":{"0":"9","1":"5"}},{"t":"case","label":"NACS v. Bd. of Governors of the Fed. Rsrv. Sys.","cite":"958 F. Supp. 2d 85","y":2013,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/958/85/","op":2,"by":{"0":"9"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"0":"4, 26, 27, 32","2":"11"}},{"t":"case","label":"NFIB v. OSHA","cite":"142 S. Ct. 661","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./142/661/","sc":1,"by":{"0":"25"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"op":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"13, 36, 41"}},{"t":"case","label":"NLRB v. O’Neill","cite":"965 F.2d 1522","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/965/1522/","by":{"0":"39"}},{"t":"case","label":"Pac. Operators Offshore, LLP v. Valladolid","cite":"565 U.S. 207","y":2012,"id":"2011/10-507","sc":1,"sum":"The Court held that the Outer Continental Shelf Lands Act extends coverage for injuries that occurred as the result of operations conducted on the outer continental shelf to an employee, as long as the employee can establish a substantial connection between the injury and the employer’s extractive operations.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"PDR Network, LLC v. Carlton & Harris Chiropractic, Inc.","cite":"139 S. Ct. 2051","y":2019,"id":"2018/17-1705","sc":1,"op":2,"ar":1,"sum":"The Court held that Fourth Circuit did not properly consider preliminary issues that determine whether a district court must accept the Federal Communication Commission's legal interpretation of the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"0":"25, 29, 31, 33, 37","1":"17, 29, 33-36, 38, 41"}},{"t":"case","label":"Penn. Dep’t of Pub. Welfare v. U.S. Dep’t of Health & Human Servs.","cite":"101 F.3d 939","y":1996,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/101/939/","by":{"0":"40","1":"44","2":"21"}},{"t":"case","label":"Reiter v. Cooper","cite":"507 U.S. 258","y":1993,"id":"1992/91-1496","sc":1,"op":2,"sum":"The Interstate Commerce Act (ICA) requires that motor common carriers charge the tariff rates they file with the Interstate Commerce Commission (ICC), 49 U. S. C. § 10762, and that such rates be \"reasonable,\" § 10701(a). Between 1984 and 1986, petitioner shippers tendered shipments to Carolina Motor Express, Inc., a motor carrier subject to ICC regulation, at negotiated rates that were lower than the applicable …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 16, 23","1":"10, 26, 28","2":"7"}},{"t":"case","label":"Richards v. Jefferson County","cite":"517 U.S. 793","y":1996,"id":"1995/95-386","sc":1,"op":1,"sum":"Authored by Justice John Paul Stevens, the Court ruled that because Richards and others received neither notice of, nor sufficient representation in, the Bedingfield litigation, that adjudication, as a matter of federal due process, may not bind them and thus cannot bar them from challenging an allegedly unconstitutional deprivation of their property.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"op":2,"ar":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"0":"14, 16, 20, 25-27, 29, 34, 42","1":"26","2":"1, 3, 6, 24, 25"}},{"t":"case","label":"Sackett v. EPA","cite":"566 U.S. 120","y":2012,"id":"2011/10-1062","sc":1,"op":1,"sum":"The Court found that homeowners have a right to go to court over a Clean Water Act order of the Environmental Protection Agency.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Shalala v. Ill. Council on Long Term Care, Inc.","cite":"529 U.S. 1","y":2000,"id":"1999/98-1109","sc":1,"sum":"The Court held that the Medicare Act barred federal-question jurisdiction of the Council's challenges to the validity of various Medicare regulations. The Court concluded that the Council must proceed instead through the special review channel that the Medicare statutes create.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Sierra Club v. Morton","cite":"405 U.S. 727","y":1972,"id":"1971/70-34","sc":1,"sum":"The Court held that a plaintiff must show that he has suffered a direct injury or will suffer a direct injury as a result of the defendant’s actions in order to have standing to sue under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Steffel v. Thompson","cite":"415 U.S. 452","y":1974,"id":"1973/72-5581","sc":1,"sum":"The Court held that the case presented an actual controversy, as the Georgia statute could interfere with Steffel’s exercise of his constitutional rights even if he was not arrested. Because the United States’ involvement in Vietnam, which Steffel was protesting, was reduced, the issue of whether or not the case still presented an active controversy would be decided by the lower court on remand.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Summers v. Earth Island Inst.","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"sum":"The Court held that the defendants did not have standing to challenge regulations of the U.S. Forest Service in the absence of a live dispute over the application of those regulations.","sumSrc":"Oyez","by":{"0":"38, 39","2":"19"}},{"t":"case","label":"Taylor v. Sturgell","cite":"553 U.S. 880","y":2008,"id":"2007/07-371","sc":1,"sum":"Writing for a unanimous Court, Justice Ruth Bader Ginsburg held that such \"nonparty preclusion\" runs up against the \"deep-rooted historic tradition that everyone should have his own day in court.\" Virtual representation should only be applied rarely and under certain exceptions to the general rule, none of which the Court found applicable in this case.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Texas v. United States","cite":"523 U.S. 296","y":1998,"id":"1997/97-29","sc":1,"sum":"The Court held that Texas's claim is not ripe for adjudication.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"38"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 2392","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"op":2,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"United States v. Clawson Med. Rehab. & Pain Care Ctr.","cite":"722 F. Supp. 1468","y":1989,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp./722/1468/","by":{"0":"39"}},{"t":"case","label":"United States v. Lindsay","cite":"346 U.S. 568","y":1954,"id":"scdb/1953-025","sc":1,"op":3,"sum":"The Government's claim \"accrued\" on the date a right to sue came into existence, rather than on the date the Act became effective, and the suit is barred. Pp. 568-571. 202 F. 2d 239, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15","1":"26"}},{"t":"case","label":"United States v. Mottaz","cite":"476 U.S. 834","y":1986,"id":"1985/85-546","sc":1,"sum":"Respondent's suit is \"a civil action... to adjudicate a disputed title to real property in which the United States claims an interest,\" within the meaning of the Quiet Title Act, and therefore is barred by that Act's 12-year limitations period.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4"}},{"t":"case","label":"Wallace v. Kato","cite":"549 U.S. 384","y":2007,"id":"2006/05-1240","sc":1,"op":4,"sum":"The opinion by Justice Antonin Scalia held that \"the statute of limitations begins to run when the alleged false imprisonment ends.\" Since false imprisonment is detention without legal process, the Court ruled, the false imprisonment ends when legal processes begin. At that point, the clock begins to run on the time limit for filing a false imprisonment claim.","sumSrc":"Oyez","by":{"0":"15","1":"26"}},{"t":"case","label":"Weyerhaeuser Co. v. U.S. Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"op":1,"sum":"An area is eligible for designation as “critical habitat” under the Endangered Species Act of 1973 only if it is habitat for the listed species; and the Secretary of the Interior’s decision not to exclude an area from critical habitat under 16 U. S. C. §1533(b)(2) is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"2, 30, 31","2":"24"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"19, 38, 39, 40"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(b)"],"by":{"0":"41"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","stext":{"head":"§702. Right of review","paras":[[0,"A person suffering legal wrong because of agency action, or adversely affected or aggrieved by agency action within the meaning of a relevant statute, is entitled to judicial review thereof. An action in a court of the United States seeking relief other than money damages and stating a claim that an agency or an officer or employee thereof acted or failed to act in an official capacity or under color of legal authority shall not be dismissed nor relief therein be denied on the ground that it is against the United States or that the United States is an indispensable party. The United States may be named as a defendant in any such action, and a judgment or decree may be entered against the United States: Provided, That any mandatory or injunctive decree shall specify the Federal officer or officers (by name or by title), and their successors in office, personally responsible for compliance. Nothing herein (1) affects other limitations on judicial review or the power or duty of the court to dismiss any action or deny relief on any other appropriate legal or equitable ground; or (2) confers authority to grant relief if any other statute that grants consent to suit expressly or impliedly forbids the relief which is sought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/702?type=usc&year=mostrecent&link-type=html"},"op":16,"ar":2,"head":"§702. Right of review","tname":"Government Organization and Employees","by":{"0":"1-4, 11-14, 18-21, 25-27, 29, 30, 36, 40, 41","1":"15"}},{"t":"usc","label":"12 U.S.C. § 1848","url":"https://www.law.cornell.edu/uscode/text/12/1848","by":{"0":"5, 26"}},{"t":"usc","label":"15 U.S.C. § 80b-13","url":"https://www.law.cornell.edu/uscode/text/15/80b-13","subs":["(a)"],"by":{"0":"26"}},{"t":"usc","label":"15 U.S.C. § 1693o-2","url":"https://www.law.cornell.edu/uscode/text/15/1693o-2","subs":["(a)(2)","(a)(4)(A)","(a)(4)(B)","(a)(3)(A)","(c)(8)"],"by":{"0":"6, 8, 7, 7","1":"4, 4, 3"}},{"t":"usc","label":"16 U.S.C. § 7804","url":"https://www.law.cornell.edu/uscode/text/16/7804","subs":["(d)(1)"],"stext":{"head":"§7804. Responsibility of the Secretary and rulemaking authority","paras":[[0,"(a) Responsibilities"],[0,"The Secretary may—"],[1,"(1) administer this chapter and any regulations issued under this chapter, except to the extent otherwise provided for in this chapter;"],[1,"(2) issue permits to vessels subject to the jurisdiction of the United States, and to owners and operators of such vessels, to fish in the Convention Area, under such terms and conditions as the Secretary may prescribe; and"],[1,"(3) if recommended by the United States Commissioners, assess and collect fees, not to exceed 3 percent of the ex-vessel value of fisheries resources harvested by vessels of the United States in fisheries conducted in the Convention Area, to recover the actual costs to the United States to carry out the functions of the Secretary under this chapter."],[0,"(b) Promulgation of regulations"],[0,"(1) In general"],[1,"The Secretary, in consultation with the Secretary of State and the Secretary of the department in which the Coast Guard is operating, may promulgate such regulations as may be necessary and appropriate to carry out the international obligations of the United States under the South Pacific Fishery Resources Convention and this chapter, including decisions adopted by the Commission."],[0,"(2) Applicability"],[1,"Regulations promulgated under this subsection shall be applicable only to a person or fishing vessel that is or has engaged in fishing, and fishery resources covered by the Convention on the Conservation and Management of High Seas Fishery Resources in the South Pacific Ocean under this chapter."],[0,"(c) Consistency with other laws"],[0,"The Secretary shall ensure the consistency, to the extent practicable, of fishery management programs administered under this chapter, the Magnuson-Stevens Fishery Conservation and Management Act (16 U.S.C. 1801 et seq.), the Tuna Conventions Act of 1950 (16 U.S.C. 951 et seq.), the South Pacific Tuna Act of 1988 (16 U.S.C. 973 et seq.), section 401 of Public Law 108–219 (16 U.S.C. 1821 note) (relating to Pacific albacore tuna), the Western and Central Pacific Fisheries Convention Implementation Act (16 U.S.C. 6901 et seq.), the National Oceanic and Atmospheric Administration Authorization Act of 1992 (Public Law 102–567) and the amendments made by that Act, and Public Law 100–629 (102 Stat. 3286)."],[0,"(d) Judicial review of regulations"],[0,"(1) In general"],[1,"Regulations promulgated by the Secretary under this chapter shall be subject to judicial review to the extent authorized by, and in accordance with, chapter 7 of title 5 if a petition for such review is filed not later than 30 days after the date on which the regulations are promulgated or the action is published in the Federal Register, as applicable."],[0,"(2) Responses"],[1,"Notwithstanding any other provision of law, the Secretary shall file a response to any petition filed in accordance with paragraph (1) not later than 30 days after the date the Secretary is served with that petition, except that the appropriate court may extend the period for filing such a response upon a showing by the Secretary of good cause for that extension."],[0,"(3) Copies of administrative record"],[1,"A response of the Secretary under paragraph (2) shall include a copy of the administrative record for the regulations that are the subject of the petition."],[0,"(4) Expedited hearings"],[1,"Upon a motion by the person who files a petition under this subsection, the appropriate court shall assign the matter for hearing at the earliest possible date."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/7804?type=usc&year=mostrecent&link-type=html"},"head":"§7804. Responsibility of the Secretary and rulemaking authority","tname":"Conservation","by":{"0":"5, 26, 27","1":"16"}},{"t":"usc","label":"21 U.S.C. § 348","url":"https://www.law.cornell.edu/uscode/text/21/348","subs":["(g)(1)"],"stext":{"head":"§348. Food additives","paras":[[0,"(a) Unsafe food additives; exception for conformity with exemption or regulation"],[0,"A food additive shall, with respect to any particular use or intended use of such additives, be deemed to be unsafe for the purposes of the application of clause (2)(C) of section 342(a) of this title, unless—"],[1,"(1) it and its use or intended use conform to the terms of an exemption which is in effect pursuant to subsection (j) of this section;"],[1,"(2) there is in effect, and it and its use or intended use are in conformity with, a regulation issued under this section prescribing the conditions under which such additive may be safely used; or"],[1,"(3) in the case of a food additive as defined in this chapter that is a food contact substance, there is—"],[2,"(A) in effect, and such substance and the use of such substance are in conformity with, a regulation issued under this section prescribing the conditions under which such additive may be safely used; or"],[2,"(B) a notification submitted under subsection (h) that is effective."],[0,"While such a regulation relating to a food additive, or such a notification under subsection (h)(1) relating to a food additive that is a food contact substance, is in effect, and has not been revoked pursuant to subsection (i), a food shall not, by reason of bearing or containing such a food additive in accordance with the regulation or notification, be considered adulterated under section 342(a)(1) of this title."],[0,"(b) Petition for regulation prescribing conditions of safe use; contents; description of production methods and controls; samples; notice of regulation"],[0,"(1) Any person may, with respect to any intended use of a food additive, file with the Secretary a petition proposing the issuance of a regulation prescribing the conditions under which such additive may be safely used."],[0,"(2) Such petition shall, in addition to any explanatory or supporting data, contain—"],[1,"(A) the name and all pertinent information concerning such food additive, including, where available, its chemical identity and composition;"],[1,"(B) a statement of the conditions of the proposed use of such additive, including all directions, recommendations, and suggestions proposed for the use of such additive, and including specimens of its proposed labeling;"],[1,"(C) all relevant data bearing on the physical or other technical effect such additive is intended to produce, and the quantity of such additive required to produce such effect;"],[1,"(D) a description of practicable methods for determining the quantity of such additive in or on food, and any substance formed in or on food, because of its use; and"],[1,"(E) full reports of investigations made with respect to the safety for use of such additive, including full information as to the methods and controls used in conducting such investigations."],[0,"(3) Upon request of the Secretary, the petitioner shall furnish (or, if the petitioner is not the manufacturer of such additive, the petitioner shall have the manufacturer of such additive furnish, without disclosure to the petitioner) a full description of the methods used in, and the facilities and controls used for, the production of such additive."],[0,"(4) Upon request of the Secretary, the petitioner shall furnish samples of the food additive involved, or articles used as components thereof, and of the food in or on which the additive is proposed to be used."],[0,"(5) Notice of the regulation proposed by the petitioner shall be published in general terms by the Secretary within thirty days after filing."],[0,"(c) Approval or denial of petition; time for issuance of order; evaluation of data; factors"],[0,"(1) The Secretary shall—"],[1,"(A) by order establish a regulation (whether or not in accord with that proposed by the petitioner) prescribing, with respect to one or more proposed uses of the food additive involved, the conditions under which such additive may be safely used (including, but not limited to, specifications as to the particular food or classes of food in or in which such additive may be used, the maximum quantity which may be used or permitted to remain in or on such food, the manner in which such additive may be added to or used in or on such food, and any directions or other labeling or packaging requirements for such additive deemed necessary by him to assure the safety of such use), and shall notify the petitioner of such order and the reasons for such action; or"],[1,"(B) by order deny the petition, and shall notify the petitioner of such order and of the reasons for such action."],[0,"(2) The order required by paragraph (1)(A) or (B) of this subsection shall be issued within ninety days after the date of filing of the petition, except that the Secretary may (prior to such ninetieth day), by written notice to the petitioner, extend such ninety-day period to such time (not more than one hundred and eighty days after the date of filing of the petition) as the Secretary deems necessary to enable him to study and investigate the petition."],[0,"(3) No such regulation shall issue if a fair evaluation of the data before the Secretary—"],[1,"(A) fails to establish that the proposed use of the food additive, under the conditions of use to be specified in the regulation, will be safe: Provided, That no additive shall be deemed to be safe if it is found to induce cancer when ingested by man or animal, or if it is found, after tests which are appropriate for the evaluation of the safety of food additives, to induce cancer in man or animal, except that this proviso shall not apply with respect to the use of a substance as an ingredient of feed for animals which are raised for food production, if the Secretary finds (i) that, under the conditions of use and feeding specified in proposed labeling and reasonably certain to be followed in practice, such additive will not adversely affect the animals for which such feed is intended, and (ii) that no residue of the additive will be found (by methods of examination prescribed or approved by the Secretary by regulations, which regulations shall not be subject to subsections (f) and (g)) in any edible portion of such animal after slaughter or in any food yielded by or derived from the living animal; or"],[1,"(B) shows that the proposed use of the additive would promote deception of the consumer in violation of this chapter or would otherwise result in adulteration or in misbranding of food within the meaning of this chapter."],[0,"(4) If, in the judgment of the Secretary, based upon a fair evaluation of the data before him, a tolerance limitation is required in order to assure that the proposed use of an additive will be safe, the Secretary—"],[1,"(A) shall not fix such tolerance limitation at a level higher than he finds to be reasonably required to accomplish the physical or other technical effect for which such additive is intended; and"],[1,"(B) shall not establish a regulation for such proposed use if he finds upon a fair evaluation of the data before him that such data do not establish that such use would accomplish the intended physical or other technical effect."],[0,"(5) In determining, for the purposes of this section, whether a proposed use of a food additive is safe, the Secretary shall consider among other relevant factors—"],[1,"(A) the probable consumption of the additive and of any substance formed in or on food because of the use of the additive;"],[1,"(B) the cumulative effect of such additive in the diet of man or animals, taking into account any chemically or pharmacologically related substance or substances in such diet; and"],[1,"(C) safety factors which in the opinion of experts qualified by scientific training and experience to evaluate the safety of food additives are generally recognized as appropriate for the use of animal experimentation data."],[0,"(d) Regulation issued on Secretary's initiative"],[0,"The Secretary may at any time, upon his own initiative, propose the issuance of a regulation prescribing, with respect to any particular use of a food additive, the conditions under which such additive may be safely used, and the reasons therefor. After the thirtieth day following publication of such a proposal, the Secretary may by order establish a regulation based upon the proposal."],[0,"(e) Publication and effective date of orders"],[0,"Any order, including any regulation established by such order, issued under subsection (c) or (d) of this section, shall be published and shall be effective upon publication, but the Secretary may stay such effectiveness if, after issuance of such order, a hearing is sought with respect to such order pursuant to subsection (f)."],[0,"(f) Objections and public hearing; basis and contents of order; statement"],[0,"(1) Within thirty days after publication of an order made pursuant to subsection (c) or (d) of this section, any person adversely affected by such an order may file objections thereto with the Secretary, specifying with particularity the provisions of the order deemed objectionable, stating reasonable grounds therefor, and requesting a public hearing upon such objections. The Secretary shall, after due notice, as promptly as possible hold such public hearing for the purpose of receiving evidence relevant and material to the issues raised by such objections. As soon as practicable after completion of the hearing, the Secretary shall by order act upon such objections and make such order public."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/348?type=usc&year=mostrecent&link-type=html"},"head":"§348. Food additives","tname":"Food and Drugs","by":{"0":"5, 26","1":"16"}},{"t":"usc","label":"26 U.S.C. § 9041","url":"https://www.law.cornell.edu/uscode/text/26/9041","subs":["(a)"],"stext":{"head":"§9041. Judicial review","paras":[[0,"(a) Review of agency action by the Commission"],[0,"Any agency action by the Commission made under the provisions of this chapter shall be subject to review by the United States Court of Appeals for the District of Columbia Circuit upon petition filed in such court within 30 days after the agency action by the Commission for which review is sought."],[0,"(b) Review procedures"],[0,"The provisions of chapter 7 of title 5, United States Code, apply to judicial review of any agency action, as defined in section 551(13) of title 5, United States Code, by the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/9041?type=usc&year=mostrecent&link-type=html"},"head":"§9041. Judicial review","tname":"Internal Revenue Code","by":{"0":"26","1":"16"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 2344","url":"https://www.law.cornell.edu/uscode/text/28/2344","stext":{"head":"§2344. Review of orders; time; notice; contents of petition; service","paras":[[0,"On the entry of a final order reviewable under this chapter, the agency shall promptly give notice thereof by service or publication in accordance with its rules. Any party aggrieved by the final order may, within 60 days after its entry, file a petition to review the order in the court of appeals wherein venue lies. The action shall be against the United States. The petition shall contain a concise statement of—"],[1,"(1) the nature of the proceedings as to which review is sought;"],[1,"(2) the facts on which venue is based;"],[1,"(3) the grounds on which relief is sought; and"],[1,"(4) the relief prayed."],[0,"The petitioner shall attach to the petition, as exhibits, copies of the order, report, or decision of the agency. The clerk shall serve a true copy of the petition on the agency and on the Attorney General by registered mail, with request for a return receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2344?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2344. Review of orders; time; notice; contents of petition; service","tname":"Judiciary and Judicial Procedure","by":{"0":"5, 25, 26, 27","1":"15, 21"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(a)"],"stext":{"head":"§2401. Time for commencing action against United States","paras":[[0,"(a) Except as provided by chapter 71 of title 41, every civil action commenced against the United States shall be barred unless the complaint is filed within six years after the right of action first accrues. The action of any person under legal disability or beyond the seas at the time the claim accrues may be commenced within three years after the disability ceases."],[0,"(b) A tort claim against the United States shall be forever barred unless it is presented in writing to the appropriate Federal agency within two years after such claim accrues or unless action is begun within six months after the date of mailing, by certified or registered mail, of notice of final denial of the claim by the agency to which it was presented."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2401?type=usc&year=mostrecent&link-type=html"},"op":7,"ar":2,"head":"§2401. Time for commencing action against United States","tname":"Judiciary and Judicial Procedure","by":{"0":"1-5, 9-15, 17-30, 33, 34, 36, 38, 39, 42","1":"16"}},{"t":"usc","label":"28 U.S.C. § 2501","url":"https://www.law.cornell.edu/uscode/text/28/2501","by":{"0":"24"}},{"t":"usc","label":"29 U.S.C. § 655","url":"https://www.law.cornell.edu/uscode/text/29/655","subs":["(f)"],"stext":{"head":"§655. Standards","paras":[[0,"(a) Promulgation by Secretary of national consensus standards and established Federal standards; time for promulgation; conflicting standards"],[0,"Without regard to chapter 5 of title 5 or to the other subsections of this section, the Secretary shall, as soon as practicable during the period beginning with the effective date of this chapter and ending two years after such date, by rule promulgate as an occupational safety or health standard any national consensus standard, and any established Federal standard, unless he determines that the promulgation of such a standard would not result in improved safety or health for specifically designated employees. In the event of conflict among any such standards, the Secretary shall promulgate the standard which assures the greatest protection of the safety or health of the affected employees."],[0,"(b) Procedure for promulgation, modification, or revocation of standards"],[0,"The Secretary may by rule promulgate, modify, or revoke any occupational safety or health standard in the following manner:"],[0,"(1) Whenever the Secretary, upon the basis of information submitted to him in writing by an interested person, a representative of any organization of employers or employees, a nationally recognized standards-producing organization, the Secretary of Health and Human Services, the National Institute for Occupational Safety and Health, or a State or political subdivision, or on the basis of information developed by the Secretary or otherwise available to him, determines that a rule should be promulgated in order to serve the objectives of this chapter, the Secretary may request the recommendations of an advisory committee appointed under section 656 of this title. The Secretary shall provide such an advisory committee with any proposals of his own or of the Secretary of Health and Human Services, together with all pertinent factual information developed by the Secretary or the Secretary of Health and Human Services, or otherwise available, including the results of research, demonstrations, and experiments. An advisory committee shall submit to the Secretary its recommendations regarding the rule to be promulgated within ninety days from the date of its appointment or within such longer or shorter period as may be prescribed by the Secretary, but in no event for a period which is longer than two hundred and seventy days."],[0,"(2) The Secretary shall publish a proposed rule promulgating, modifying, or revoking an occupational safety or health standard in the Federal Register and shall afford interested persons a period of thirty days after publication to submit written data or comments. Where an advisory committee is appointed and the Secretary determines that a rule should be issued, he shall publish the proposed rule within sixty days after the submission of the advisory committee's recommendations or the expiration of the period prescribed by the Secretary for such submission."],[0,"(3) On or before the last day of the period provided for the submission of written data or comments under paragraph (2), any interested person may file with the Secretary written objections to the proposed rule, stating the grounds therefor and requesting a public hearing on such objections. Within thirty days after the last day for filing such objections, the Secretary shall publish in the Federal Register a notice specifying the occupational safety or health standard to which objections have been filed and a hearing requested, and specifying a time and place for such hearing."],[0,"(4) Within sixty days after the expiration of the period provided for the submission of written data or comments under paragraph (2), or within sixty days after the completion of any hearing held under paragraph (3), the Secretary shall issue a rule promulgating, modifying, or revoking an occupational safety or health standard or make a determination that a rule should not be issued. Such a rule may contain a provision delaying its effective date for such period (not in excess of ninety days) as the Secretary determines may be necessary to insure that affected employers and employees will be informed of the existence of the standard and of its terms and that employers affected are given an opportunity to familiarize themselves and their employees with the existence of the requirements of the standard."],[0,"(5) The Secretary, in promulgating standards dealing with toxic materials or harmful physical agents under this subsection, shall set the standard which most adequately assures, to the extent feasible, on the basis of the best available evidence, that no employee will suffer material impairment of health or functional capacity even if such employee has regular exposure to the hazard dealt with by such standard for the period of his working life. Development of standards under this subsection shall be based upon research, demonstrations, experiments, and such other information as may be appropriate. In addition to the attainment of the highest degree of health and safety protection for the employee, other considerations shall be the latest available scientific data in the field, the feasibility of the standards, and experience gained under this and other health and safety laws. Whenever practicable, the standard promulgated shall be expressed in terms of objective criteria and of the performance desired."],[0,"(6)(A) Any employer may apply to the Secretary for a temporary order granting a variance from a standard or any provision thereof promulgated under this section. Such temporary order shall be granted only if the employer files an application which meets the requirements of clause (B) and establishes that (i) he is unable to comply with a standard by its effective date because of unavailability of professional or technical personnel or of materials and equipment needed to come into compliance with the standard or because necessary construction or alteration of facilities cannot be completed by the effective date, (ii) he is taking all available steps to safeguard his employees against the hazards covered by the standard, and (iii) he has an effective program for coming into compliance with the standard as quickly as practicable. Any temporary order issued under this paragraph shall prescribe the practices, means, methods, operations, and processes which the employer must adopt and use while the order is in effect and state in detail his program for coming into compliance with the standard. Such a temporary order may be granted only after notice to employees and an opportunity for a hearing: Provided, That the Secretary may issue one interim order to be effective until a decision is made on the basis of the hearing. No temporary order may be in effect for longer than the period needed by the employer to achieve compliance with the standard or one year, whichever is shorter, except that such an order may be renewed not more than twice (I) so long as the requirements of this paragraph are met and (II) if an application for renewal is filed at least 90 days prior to the expiration date of the order. No interim renewal of an order may remain in effect for longer than 180 days."],[0,"(B) An application for a temporary order under this paragraph (6) shall contain:"],[1,"(i) a specification of the standard or portion thereof from which the employer seeks a variance,"],[1,"(ii) a representation by the employer, supported by representations from qualified persons having firsthand knowledge of the facts represented, that he is unable to comply with the standard or portion thereof and a detailed statement of the reasons therefor,"],[1,"(iii) a statement of the steps he has taken and will take (with specific dates) to protect employees against the hazard covered by the standard,"],[1,"(iv) a statement of when he expects to be able to comply with the standard and what steps he has taken and what steps he will take (with dates specified) to come into compliance with the standard, and"],[1,"(v) a certification that he has informed his employees of the application by giving a copy thereof to their authorized representative, posting a statement giving a summary of the application and specifying where a copy may be examined at the place or places where notices to employees are normally posted, and by other appropriate means."],[0,"A description of how employees have been informed shall be contained in the certification. The information to employees shall also inform them of their right to petition the Secretary for a hearing."],[0,"(C) The Secretary is authorized to grant a variance from any standard or portion thereof whenever he determines, or the Secretary of Health and Human Services certifies, that such variance is necessary to permit an employer to participate in an experiment approved by him or the Secretary of Health and Human Services designed to demonstrate or validate new and improved techniques to safeguard the health or safety of workers."],[0,"(7) Any standard promulgated under this subsection shall prescribe the use of labels or other appropriate forms of warning as are necessary to insure that employees are apprised of all hazards to which they are exposed, relevant symptoms and appropriate emergency treatment, and proper conditions and precautions of safe use or exposure. Where appropriate, such standard shall also prescribe suitable protective equipment and control or technological procedures to be used in connection with such hazards and shall provide for monitoring or measuring employee exposure at such locations and intervals, and in such manner as may be necessary for the protection of employees. In addition, where appropriate, any such standard shall prescribe the type and frequency of medical examinations or other tests which shall be made available, by the employer or at his cost, to employees exposed to such hazards in order to most effectively determine whether the health of such employees is adversely affected by such exposure. In the event such medical examinations are in the nature of research, as determined by the Secretary of Health and Human Services, such examinations may be furnished at the expense of the Secretary of Health and Human Services. The results of such examinations or tests shall be furnished only to the Secretary or the Secretary of Health and Human Services, and, at the request of the employee, to his physician. The Secretary, in consultation with the Secretary of Health and Human Services, may by rule promulgated pursuant to section 553 of title 5, make appropriate modifications in the foregoing requirements relating to the use of labels or other forms of warning, monitoring or measuring, and medical examinations, as may be warranted by experience, information, or medical or technological developments acquired subsequent to the promulgation of the relevant standard."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/655?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§655. Standards","tname":"Labor","by":{"0":"5, 26","1":"16"}},{"t":"usc","label":"33 U.S.C. § 1369","url":"https://www.law.cornell.edu/uscode/text/33/1369","subs":["(b)(1)","(b)(2)"],"stext":{"head":"§1369. Administrative procedure and judicial review","paras":[[0,"(a) Subpenas"],[0,"(1) For purposes of obtaining information under section 1315 of this title, or carrying out section 1367(e) of this title, the Administrator may issue subpenas for the attendance and testimony of witnesses and the production of relevant papers, books, and documents, and he may administer oaths. Except for effluent data, upon a showing satisfactory to the Administrator that such papers, books, documents, or information or particular part thereof, if made public, would divulge trade secrets or secret processes, the Administrator shall consider such record, report, or information or particular portion thereof confidential in accordance with the purposes of section 1905 of title 18, except that such paper, book, document, or information may be disclosed to other officers, employees, or authorized representatives of the United States concerned with carrying out this chapter, or when relevant in any proceeding under this chapter. Witnesses summoned shall be paid the same fees and mileage that are paid witnesses in the courts of the United States. In case of contumacy or refusal to obey a subpena served upon any person under this subsection, the district court of the United States for any district in which such person is found or resides or transacts business, upon application by the United States and after notice to such person, shall have jurisdiction to issue an order requiring such person to appear and give testimony before the Administrator, to appear and produce papers, books, and documents before the Administrator, or both, and any failure to obey such order of the court may be punished by such court as a contempt thereof."],[0,"(2) The district courts of the United States are authorized, upon application by the Administrator, to issue subpenas for attendance and testimony of witnesses and the production of relevant papers, books, and documents, for purposes of obtaining information under sections 1314(b) and (c) of this title. Any papers, books, documents, or other information or part thereof, obtained by reason of such a subpena shall be subject to the same requirements as are provided in paragraph (1) of this subsection."],[0,"(b) Review of Administrator's actions; selection of court; fees"],[0,"(1) Review of the Administrator's action (A) in promulgating any standard of performance under section 1316 of this title, (B) in making any determination pursuant to section 1316(b)(1)(C) of this title, (C) in promulgating any effluent standard, prohibition, or pretreatment standard under section 1317 of this title, (D) in making any determination as to a State permit program submitted under section 1342(b) of this title, (E) in approving or promulgating any effluent limitation or other limitation under section 1311, 1312, 1316, or 1345 of this title, (F) in issuing or denying any permit under section 1342 of this title, and (G) in promulgating any individual control strategy under section 1314(l) of this title, may be had by any interested person in the Circuit Court of Appeals of the United States for the Federal judicial district in which such person resides or transacts business which is directly affected by such action upon application by such person. Any such application shall be made within 120 days from the date of such determination, approval, promulgation, issuance or denial, or after such date only if such application is based solely on grounds which arose after such 120th day."],[0,"(2) Action of the Administrator with respect to which review could have been obtained under paragraph (1) of this subsection shall not be subject to judicial review in any civil or criminal proceeding for enforcement."],[0,"(3) Award of fees.—In any judicial proceeding under this subsection, the court may award costs of litigation (including reasonable attorney and expert witness fees) to any prevailing or substantially prevailing party whenever it determines that such award is appropriate."],[0,"(4) Discharges incidental to normal operation of vessels.—"],[1,"(A) In general.—Except as provided in subparagraph (B), any interested person may file a petition for review of a final agency action under section 1322(p) of this title of the Administrator or the Secretary of the department in which the Coast Guard is operating in accordance with the requirements of this subsection."],[1,"(B) Venue exception.—Subject to section 1322(p)(7)(C)(v) of this title, a petition for review of a final agency action under section 1322(p) of this title of the Administrator or the Secretary of the department in which the Coast Guard is operating may be filed only in the United States Court of Appeals for the District of Columbia Circuit."],[0,"(c) Additional evidence"],[0,"In any judicial proceeding brought under subsection (b) of this section in which review is sought of a determination under this chapter required to be made on the record after notice and opportunity for hearing, if any party applies to the court for leave to adduce additional evidence, and shows to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Administrator, the court may order such additional evidence (and evidence in rebuttal thereof) to be taken before the Administrator, in such manner and upon such terms and conditions as the court may deem proper. The Administrator may modify his findings as to the facts, or make new findings, by reason of the additional evidence so taken and he shall file such modified or new findings, and his recommendation, if any, for the modification or setting aside of his original determination, with the return of such additional evidence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1369?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1369. Administrative procedure and judicial review","tname":"Navigation and Navigable Waters","by":{"0":"26, 27, 29","1":"16"}},{"t":"usc","label":"39 U.S.C. § 3663","url":"https://www.law.cornell.edu/uscode/text/39/3663","by":{"0":"5, 26"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(b)(2)"],"by":{"0":"29"}},{"t":"usc","label":"42 U.S.C. § 9613","url":"https://www.law.cornell.edu/uscode/text/42/9613","subs":["(a)"],"stext":{"head":"§9613. Civil proceedings","paras":[[0,"(a) Review of regulations in Circuit Court of Appeals of the United States for the District of Columbia"],[0,"Review of any regulation promulgated under this chapter may be had upon application by any interested person only in the Circuit Court of Appeals of the United States for the District of Columbia. Any such application shall be made within ninety days from the date of promulgation of such regulations. Any matter with respect to which review could have been obtained under this subsection shall not be subject to judicial review in any civil or criminal proceeding for enforcement or to obtain damages or recovery of response costs."],[0,"(b) Jurisdiction; venue"],[0,"Except as provided in subsections (a) and (h) of this section, the United States district courts shall have exclusive original jurisdiction over all controversies arising under this chapter, without regard to the citizenship of the parties or the amount in controversy. Venue shall lie in any district in which the release or damages occurred, or in which the defendant resides, may be found, or has his principal office. For the purposes of this section, the Fund shall reside in the District of Columbia."],[0,"(c) Controversies or other matters resulting from tax collection or tax regulation review"],[0,"The provisions of subsections (a) and (b) of this section shall not apply to any controversy or other matter resulting from the assessment of collection of any tax, as provided by subchapter II 1 of this chapter, or to the review of any regulation promulgated under title 26."],[0,"(d) Litigation commenced prior to December 11, 1980"],[0,"No provision of this chapter shall be deemed or held to moot any litigation concerning any release of any hazardous substance, or any damages associated therewith, commenced prior to December 11, 1980."],[0,"(e) Nationwide service of process"],[0,"In any action by the United States under this chapter, process may be served in any district where the defendant is found, resides, transacts business, or has appointed an agent for the service of process."],[0,"(f) Contribution"],[0,"(1) Contribution"],[1,"Any person may seek contribution from any other person who is liable or potentially liable under section 9607(a) of this title, during or following any civil action under section 9606 of this title or under section 9607(a) of this title. Such claims shall be brought in accordance with this section and the Federal Rules of Civil Procedure, and shall be governed by Federal law. In resolving contribution claims, the court may allocate response costs among liable parties using such equitable factors as the court determines are appropriate. Nothing in this subsection shall diminish the right of any person to bring an action for contribution in the absence of a civil action under section 9606 of this title or section 9607 of this title."],[0,"(2) Settlement"],[1,"A person who has resolved its liability to the United States or a State in an administrative or judicially approved settlement shall not be liable for claims for contribution regarding matters addressed in the settlement. Such settlement does not discharge any of the other potentially liable persons unless its terms so provide, but it reduces the potential liability of the others by the amount of the settlement."],[0,"(3) Persons not party to settlement"],[1,"(A) If the United States or a State has obtained less than complete relief from a person who has resolved its liability to the United States or the State in an administrative or judicially approved settlement, the United States or the State may bring an action against any person who has not so resolved its liability."],[1,"(B) A person who has resolved its liability to the United States or a State for some or all of a response action or for some or all of the costs of such action in an administrative or judicially approved settlement may seek contribution from any person who is not party to a settlement referred to in paragraph (2)."],[1,"(C) In any action under this paragraph, the rights of any person who has resolved its liability to the United States or a State shall be subordinate to the rights of the United States or the State. Any contribution action brought under this paragraph shall be governed by Federal law."],[0,"(g) Period in which action may be brought"],[0,"(1) Actions for natural resource damages"],[1,"Except as provided in paragraphs (3) and (4), no action may be commenced for damages (as defined in section 9601(6) of this title) under this chapter, unless that action is commenced within 3 years after the later of the following:"],[2,"(A) The date of the discovery of the loss and its connection with the release in question."],[2,"(B) The date on which regulations are promulgated under section 9651(c) of this title."],[1,"With respect to any facility listed on the National Priorities List (NPL), any Federal facility identified under section 9620 of this title (relating to Federal facilities), or any vessel or facility at which a remedial action under this chapter is otherwise scheduled, an action for damages under this chapter must be commenced within 3 years after the completion of the remedial action (excluding operation and maintenance activities) in lieu of the dates referred to in subparagraph (A) or (B). In no event may an action for damages under this chapter with respect to such a vessel or facility be commenced (i) prior to 60 days after the Federal or State natural resource trustee provides to the President and the potentially responsible party a notice of intent to file suit, or (ii) before selection of the remedial action if the President is diligently proceeding with a remedial investigation and feasibility study under section 9604(b) of this title or section 9620 of this title (relating to Federal facilities). The limitation in the preceding sentence on commencing an action before giving notice or before selection of the remedial action does not apply to actions filed on or before October 17, 1986."],[0,"(2) Actions for recovery of costs"],[1,"An initial action for recovery of the costs referred to in section 9607 of this title must be commenced—"],[2,"(A) for a removal action, within 3 years after completion of the removal action, except that such cost recovery action must be brought within 6 years after a determination to grant a waiver under section 9604(c)(1)(C) of this title for continued response action; and"],[2,"(B) for a remedial action, within 6 years after initiation of physical on-site construction of the remedial action, except that, if the remedial action is initiated within 3 years after the completion of the removal action, costs incurred in the removal action may be recovered in the cost recovery action brought under this subparagraph."],[1,"In any such action described in this subsection, the court shall enter a declaratory judgment on liability for response costs or damages that will be binding on any subsequent action or actions to recover further response costs or damages. A subsequent action or actions under section 9607 of this title for further response costs at the vessel or facility may be maintained at any time during the response action, but must be commenced no later than 3 years after the date of completion of all response action. Except as otherwise provided in this paragraph, an action may be commenced under section 9607 of this title for recovery of costs at any time after such costs have been incurred."],[0,"(3) Contribution"],[1,"No action for contribution for any response costs or damages may be commenced more than 3 years after—"],[2,"(A) the date of judgment in any action under this chapter for recovery of such costs or damages, or"],[2,"(B) the date of an administrative order under section 9622(g) of this title (relating to de minimis settlements) or 9622(h) of this title (relating to cost recovery settlements) or entry of a judicially approved settlement with respect to such costs or damages."],[0,"(4) Subrogation"],[1,"No action based on rights subrogated pursuant to this section by reason of payment of a claim may be commenced under this subchapter more than 3 years after the date of payment of such claim."],[0,"(5) Actions to recover indemnification payments"],[1,"Notwithstanding any other provision of this subsection, where a payment pursuant to an indemnification agreement with a response action contractor is made under section 9619 of this title, an action under section 9607 of this title for recovery of such indemnification payment from a potentially responsible party may be brought at any time before the expiration of 3 years from the date on which such payment is made."],[0,"(6) Minors and incompetents"],[1,"The time limitations contained herein shall not begin to run—"],[2,"(A) against a minor until the earlier of the date when such minor reaches 18 years of age or the date on which a legal representative is duly appointed for such minor, or"],[2,"(B) against an incompetent person until the earlier of the date on which such incompetent's incompetency ends or the date on which a legal representative is duly appointed for such incompetent."],[0,"(h) Timing of review"],[0,"No Federal court shall have jurisdiction under Federal law other than under section 1332 of title 28 (relating to diversity of citizenship jurisdiction) or under State law which is applicable or relevant and appropriate under section 9621 of this title (relating to cleanup standards) to review any challenges to removal or remedial action selected under section 9604 of this title, or to review any order issued under section 9606(a) of this title, in any action except one of the following:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9613?type=usc&year=mostrecent&link-type=html"},"head":"§9613. Civil proceedings","tname":"The Public Health and Welfare","by":{"0":"29","1":"17"}},{"t":"usc","label":"44 U.S.C. § 1505","url":"https://www.law.cornell.edu/uscode/text/44/1505","subs":["(a)"],"by":{"0":"41"}},{"t":"usc","label":"44 U.S.C. § 3101","url":"https://www.law.cornell.edu/uscode/text/44/3101","by":{"0":"41","1":"44"}},{"t":"usc","label":"49 U.S.C. § 30161","url":"https://www.law.cornell.edu/uscode/text/49/30161","subs":["(a)"],"by":{"0":"26","1":"16, 17"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"0":"6","1":"4"}},{"t":"reg","label":"Debit Card Interchange Fees and Routing, 75 Fed. Reg. 81722","url":"https://www.govinfo.gov/link/fr/75/81722","by":{"0":"7","1":"4"}},{"t":"reg","label":"Debit Card Interchange Fees and Routing, 76 Fed. Reg. 43394","url":"https://www.govinfo.gov/link/fr/76/43394","by":{"0":"6-8","1":"3, 4"}},{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"1":"37, 39"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"op":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"1":"11, 12, 14"}},{"t":"case","label":"Block v. North Dakota ex rel. Board of University & School Lands","cite":"461 U.S. 273","y":1983,"id":"1982/81-2337","sc":1,"sum":"North Dakota filed suit in Federal District Court against several federal officials to resolve a dispute as to ownership of certain portions of a riverbed within the State. The United States claims title to most of the disputed area on the basis of its status as a riparian landowner on a nonnavigable river, while the State asserts that the river was navigable when North Dakota was admitted to the Union in 1889 and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Citizens to Preserve Overton Park, Inc. v. Volpe","cite":"401 U.S. 402","y":1971,"id":"1970/1066","sc":1,"sum":"Under § 4 (f) of the Department. of Transportation Act of 1966 and § 138 of the Federal-Aid Highway Act of 1968, the Secretary of Transportation may not authorize use of federal funds to finance construction of highways through public parks if a \"feasible and prudent\" alternative route exists. If no such route is available, he may approve construction only if there has been \"all possible planning to minimize harm\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37, 44"}},{"t":"case","label":"Coal River Energy, LLC v. Jewell","cite":"751 F.3d 659","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/751/659/","sum":"Explaining that a limitations bar on facial challenges “does not preclude a challenge when the government actually applies its regulation against a party”.","sumSrc":"brief:1","by":{"1":"29, 30, 34, 36, 41","2":"6, 19, 24"}},{"t":"case","label":"Darby v. Cisneros","cite":"509 U.S. 137","y":1993,"id":"1992/91-2045","sc":1,"ar":2,"sum":"Federal courts do not have the authority to require a plaintiff to exhaust available administrative remedies before seeking judicial review under the APA, where neither the relevant statute nor agency rules specifically mandate exhaustion as a prerequisite to judicial review. The language of § 10(c) of the APA is explicit that an appeal to \"superior agency authority\" is a prerequisite to judicial review only when …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23","2":"13, 16"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"sum":"Petitioner accounting firm was retained to audit periodically a brokerage firm's books and records. Respondents, who were customers of the brokerage firm, invested in a securities scheme ultimately revealed as fraudulent and perpetrated by the firm's president and principal stockholder. After the fraud came to light, respondents filed an action for damages against petitioner under § 10 (b) of the Securities Exchange …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Federal Communications Commission v. Prometheus Radio Project","cite":"141 S. Ct. 1150","y":2021,"id":"2020/19-1231","sc":1,"sum":"The Federal Communications Commission’s 2017 decision to repeal or modify three of its media ownership rules was not arbitrary or capricious for purposes of the Administrative Procedure Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18"}},{"t":"case","label":"Green v. Brennan","cite":"578 U.S. 547","y":2016,"id":"2015/14-613","sc":1,"op":10,"sum":"The Court held that the 45-day period in which an employee must file a constructive discharge claim under federal employment discrimination law begins to run on the date the employee resigns.","sumSrc":"Oyez","by":{"1":"26, 28","2":"8"}},{"t":"case","label":"Griffin v. HM Florida-ORL, LLC","cite":"2023 WL 7928928","y":2023,"court":"Nov. 16","by":{"1":"42"}},{"t":"case","label":"Hardin v. Jackson","cite":"625 F.3d 739","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/625/739/","by":{"1":"13, 14"}},{"t":"case","label":"Harris v. Federal Aviation Administration","cite":"353 F.3d 1006","y":2004,"url":"https://www.courtlistener.com/c/F.3d/353/1006/","op":1,"by":{"1":"13"}},{"t":"case","label":"Independent Community Bankers of America v. Board of Governors of the Federal Reserve System","cite":"195 F.3d 28","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/195/28/","op":1,"by":{"1":"40, 41"}},{"t":"case","label":"Irwin v. Department of Veterans Affairs","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Izaak Walton League of America, Inc. v. Kimbell","cite":"558 F.3d 751","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/558/751/","by":{"1":"7"}},{"t":"case","label":"JEM Broadcasting Co. v. Federal Communications Commission","cite":"22 F.3d 320","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/22/320/","by":{"1":"17, 30, 35","2":"6"}},{"t":"case","label":"Linney’s Pizza, LLC v. Board of Governors of the Federal Reserve System","cite":"2023 WL 6050569","y":2023,"court":"E.D. Ky. Sept. 15","op":1,"by":{"1":"19"}},{"t":"case","label":"Lujan v. National Wildlife Federation","cite":"497 U.S. 871","y":1990,"id":"1989/89-640","sc":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Supreme Court held that NWF did not have standing to challenge the land-use designations. The two timely affidavits were not enough to show that the group members had actually been affected by the BLM decisions.","sumSrc":"Oyez","by":{"1":"2, 39","2":"13"}},{"t":"case","label":"National Association of Manufacturers v. Department of Defense","cite":"583 U.S. 109","y":2018,"id":"2017/16-299","sc":1,"op":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"1":"2, 12"}},{"t":"case","label":"Natural Resources Defense Council v. Nuclear Regulatory Commission","cite":"666 F.2d 595","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/666/595/","op":3,"by":{"1":"44"}},{"t":"case","label":"Odyssey Logistics & Technology Corp. v. Iancu","cite":"959 F.3d 1104","y":2020,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/959/1104/","op":1,"by":{"1":"14"}},{"t":"case","label":"Order of Railroad Telegraphers v. Railway Express Agency, Inc.","cite":"321 U.S. 342","y":1944,"id":"scdb/1943-094","sc":1,"op":2,"sum":"1. Failure of the carrier to give notice, to the representative of the employees, of an intended change affecting rates of pay of certain individual employees was in violation of § 6 of the Railway Labor Act of 1926, applicable to the collective agreement in question, and rendered ineffective the individual agreements entered into; and the award of the Adjustment Board, based on the collective agreement, was in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Raton Gas Transmission Co. v. Federal Energy Regulatory Commission","cite":"852 F.2d 612","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/852/612/","by":{"1":"18"}},{"t":"case","label":"Reading Co. v. Koons","cite":"271 U.S. 58","y":1926,"id":"scdb/1925-153","sc":1,"op":7,"ar":2,"sum":"Section 6 of the Employers' Liability Act, providing \"That no action shall be maintained under this Act unless commenced within two years from the day the cause of action accrued,\" is to be construed as allowing, in death cases, two years from the time of death-not two years from the appointment of the administrator. P. 60. 281 Pa. 270, reversed. READING CO. v. KOONS..58","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13, 26, 27, 30","2":"8"}},{"t":"case","label":"Rotella v. Wood","cite":"528 U.S. 549","y":2000,"id":"1999/98-896","sc":1,"op":1,"sum":"The Court held that Rotella's action was not timely, because the start of the 4-year limitations period applicable to a civil RICO action was not governed by an \"injury and pattern discovery\" accrual rule under which such a civil claim would accrue only when the claimant discovered, or should have discovered, both an injury and a pattern of racketeering activity.","sumSrc":"Oyez","by":{"1":"17, 34, 46"}},{"t":"case","label":"Sackett v. Environmental Protection Agency","cite":"598 U.S. 651","y":2023,"id":"2022/21-454","sc":1,"sum":"The Clean Water Act extends only to wetlands that have a continuous surface connection with “waters” of the United States—i.e., with a relatively permanent body of water connected to traditional interstate navigable waters, 33 U. S. C. §1362(7)—making it difficult to determine where the water ends and the wetland begins.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12"}},{"t":"case","label":"Securities & Exchange Commission v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"op":3,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Shiny Rock Mining Corp. v. United States","cite":"906 F.2d 1362","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/906/1362/","op":1,"by":{"1":"14"}},{"t":"case","label":"Sierra Club v. Slater","cite":"120 F.3d 623","y":1997,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/120/623/","by":{"1":"14"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"op":1,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"42"}},{"t":"case","label":"United States Steel Corp. v. Astrue","cite":"495 F.3d 1272","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/495/1272/","by":{"1":"14"}},{"t":"case","label":"Wilkins v. United States","cite":"598 U.S. 152","y":2023,"id":"2022/21-1164","sc":1,"sum":"The Quiet Title Act’s 12-year statute of limitations, 28 U. S. C. §2409a(g), is a nonjurisdictional claims-processing rule.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31"}},{"t":"case","label":"Wilson v. Garcia","cite":"471 U.S. 261","y":1985,"id":"1984/83-2146","sc":1,"sum":"The Court held that, in situations where a federal action does not have a statute of limitations, the practice has been to adopt a local limitation as long as that limitation is not inconsistent with a federal law or policy.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Wind River Mining Corp. v. United States","cite":"946 F.2d 710","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/946/710/","op":1,"by":{"1":"41"}},{"t":"case","label":"Wong v. Doar","cite":"571 F.3d 247","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/571/247/","op":1,"by":{"1":"13"}},{"t":"law","label":"Pub. L. No. 94-574","url":"https://www.govinfo.gov/link/statute/90/2721","by":{"1":"13"}},{"t":"usc","label":"28 U.S.C. § 2341","url":"https://www.law.cornell.edu/uscode/text/28/2341","by":{"1":"15"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","stext":{"head":"§2342. Jurisdiction of court of appeals","paras":[[0,"The court of appeals (other than the United States Court of Appeals for the Federal Circuit) has exclusive jurisdiction to enjoin, set aside, suspend (in whole or in part), or to determine the validity of—"],[1,"(1) all final orders of the Federal Communication Commission made reviewable by section 402(a) of title 47;"],[1,"(2) all final orders of the Secretary of Agriculture made under chapters 9 and 20A of title 7, except orders issued under sections 210(e), 217a, and 499g(a) of title 7;"],[1,"(3) all rules, regulations, or final orders of—"],[2,"(A) the Secretary of Transportation issued pursuant to section 50501, 50502, 56101–56104, or 57109 of title 46 or pursuant to part B or C of subtitle IV, subchapter III of chapter 311, chapter 313, or chapter 315 of title 49; and"],[2,"(B) the Federal Maritime Commission issued pursuant to section 305,1 41304, 41308, or 41309 or chapter 421 or 441 of title 46;"],[1,"(4) all final orders of the Atomic Energy Commission made reviewable by section 2239 of title 42;"],[1,"(5) all rules, regulations, or final orders of the Surface Transportation Board made reviewable by section 2321 of this title;"],[1,"(6) all final orders under section 812 of the Fair Housing Act; and"],[1,"(7) all final agency actions described in section 20114(c) of title 49."],[0,"Jurisdiction is invoked by filing a petition as provided by section 2344 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2342?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§2342. Jurisdiction of court of appeals","tname":"Judiciary and Judicial Procedure","by":{"1":"15, 36"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"2"}},{"t":"usc","label":"5 U.S.C. § 703","url":"https://www.law.cornell.edu/uscode/text/5/703","stext":{"head":"§703. Form and venue of proceeding","paras":[[0,"The form of proceeding for judicial review is the special statutory review proceeding relevant to the subject matter in a court specified by statute or, in the absence or inadequacy thereof, any applicable form of legal action, including actions for declaratory judgments or writs of prohibitory or mandatory injunction or habeas corpus, in a court of competent jurisdiction. If no special statutory review proceeding is applicable, the action for judicial review may be brought against the United States, the agency by its official title, or the appropriate officer. Except to the extent that prior, adequate, and exclusive opportunity for judicial review is provided by law, agency action is subject to judicial review in civil or criminal proceedings for judicial enforcement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/703?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§703. Form and venue of proceeding","tname":"Government Organization and Employees","by":{"1":"15"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","stext":{"head":"§704. Actions reviewable","paras":[[0,"Agency action made reviewable by statute and final agency action for which there is no other adequate remedy in a court are subject to judicial review. A preliminary, procedural, or intermediate agency action or ruling not directly reviewable is subject to review on the review of the final agency action. Except as otherwise expressly required by statute, agency action otherwise final is final for the purposes of this section whether or not there has been presented or determined an application for a declaratory order, for any form of reconsideration, or, unless the agency otherwise requires by rule and provides that the action meanwhile is inoperative, for an appeal to superior agency authority."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/704?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§704. Actions reviewable","tname":"Government Organization and Employees","by":{"1":"15"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"1":"15"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"1":"15"}},{"t":"law","label":"Pub. L. No. 95-563","url":"https://www.govinfo.gov/link/statute/92/2389","by":{"1":"24"}},{"t":"usc","label":"15 U.S.C. § 1693","url":"https://www.law.cornell.edu/uscode/text/15/1693","by":{"1":"4"}},{"t":"usc","label":"21 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/21/301","by":{"1":"16"}},{"t":"usc","label":"21 U.S.C. § 360kk","url":"https://www.law.cornell.edu/uscode/text/21/360kk","subs":["(d)(1)"],"by":{"1":"16"}},{"t":"usc","label":"21 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/21/371","subs":["(f)(1)"],"by":{"1":"16, 21"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)"],"by":{"1":"15"}},{"t":"usc","label":"15 U.S.C. § 57a","url":"https://www.law.cornell.edu/uscode/text/15/57a","subs":["(e)(1)(A)"],"by":{"1":"16"}},{"t":"usc","label":"15 U.S.C. § 78y","url":"https://www.law.cornell.edu/uscode/text/15/78y","subs":["(b)(1)"],"stext":{"head":"§78y. Court review of orders and rules","paras":[[0,"(a) Final Commission orders; persons aggrieved; petition; record; findings; affirmance, modification, enforcement, or setting aside of orders; remand to adduce additional evidence"],[0,"(1) A person aggrieved by a final order of the Commission entered pursuant to this chapter may obtain review of the order in the United States Court of Appeals for the circuit in which he resides or has his principal place of business, or for the District of Columbia Circuit, by filing in such court, within sixty days after the entry of the order, a written petition requesting that the order be modified or set aside in whole or in part."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated by the Commission for that purpose. Thereupon the Commission shall file in the court the record on which the order complained of is entered, as provided in section 2112 of title 28 and the Federal Rules of Appellate Procedure."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the record, to affirm or modify and enforce or to set aside the order in whole or in part."],[0,"(4) The findings of the Commission as to the facts, if supported by substantial evidence, are conclusive."],[0,"(5) If either party applies to the court for leave to adduce additional evidence and shows to the satisfaction of the court that the additional evidence is material and that there was reasonable ground for failure to adduce it before the Commission, the court may remand the case to the Commission for further proceedings, in whatever manner and on whatever conditions the court considers appropriate. If the case is remanded to the Commission, it shall file in the court a supplemental record containing any new evidence, any further or modified findings, and any new order."],[0,"(b) Commission rules; persons adversely affected; petition; record; affirmance, enforcement, or setting aside of rules; findings; transfer of proceedings"],[0,"(1) A person adversely affected by a rule of the Commission promulgated pursuant to section 78f, 78i(h)(2), 78k, 78k–1, 78o(c)(5) or (6), 78o–3, 78q, 78q–1, or 78s of this title may obtain review of this rule in the United States Court of Appeals for the circuit in which he resides or has his principal place of business or for the District of Columbia Circuit, by filing in such court, within sixty days after the promulgation of the rule, a written petition requesting that the rule be set aside."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated for that purpose. Thereupon, the Commission shall file in the court the rule under review and any documents referred to therein, the Commission's notice of proposed rulemaking and any documents referred to therein, all written submissions and the transcript of any oral presentations in the rulemaking, factual information not included in the foregoing that was considered by the Commission in the promulgation of the rule or proffered by the Commission as pertinent to the rule, the report of any advisory committee received or considered by the Commission in the rulemaking, and any other materials prescribed by the court."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the materials set forth in paragraph (2) of this subsection, to affirm and enforce or to set aside the rule."],[0,"(4) The findings of the Commission as to the facts identified by the Commission as the basis, in whole or in part, of the rule, if supported by substantial evidence, are conclusive. The court shall affirm and enforce the rule unless the Commission's action in promulgating the rule is found to be arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law; contrary to constitutional right, power, privilege, or immunity; in excess of statutory jurisdiction, authority, or limitations, or short of statutory right; or without observance of procedure required by law."],[0,"(5) If proceedings have been instituted under this subsection in two or more courts of appeals with respect to the same rule, the Commission shall file the materials set forth in paragraph (2) of this subsection in that court in which a proceeding was first instituted. The other courts shall thereupon transfer all such proceedings to the court in which the materials have been filed. For the convenience of the parties in the interest of justice that court may thereafter transfer all the proceedings to any other court of appeals."],[0,"(c) Objections not urged before Commission; stay of orders and rules; transfer of enforcement or review proceedings"],[0,"(1) No objection to an order or rule of the Commission, for which review is sought under this section, may be considered by the court unless it was urged before the Commission or there was reasonable ground for failure to do so."],[0,"(2) The filing of a petition under this section does not operate as a stay of the Commission's order or rule. Until the court's jurisdiction becomes exclusive, the Commission may stay its order or rule pending judicial review if it finds that justice so requires. After the filing of a petition under this section, the court, on whatever conditions may be required and to the extent necessary to prevent irreparable injury, may issue all necessary and appropriate process to stay the order or rule or to preserve status or rights pending its review; but (notwithstanding section 705 of title 5) no such process may be issued by the court before the filing of the record or the materials set forth in subsection (b)(2) of this section unless: (A) the Commission has denied a stay or failed to grant requested relief, (B) a reasonable period has expired since the filing of an application for a stay without a decision by the Commission, or (C) there was reasonable ground for failure to apply to the Commission."],[0,"(3) When the same order or rule is the subject of one or more petitions for review filed under this section and an action for enforcement filed in a district court of the United States under section 78u(d) or (e) of this title, that court in which the petition or the action is first filed has jurisdiction with respect to the order or rule to the exclusion of any other court, and thereupon all such proceedings shall be transferred to that court; but, for the convenience of the parties in the interest of justice, that court may thereafter transfer all the proceedings to any other court of appeals or district court of the United States, whether or not a petition for review or an action for enforcement was originally filed in the transferee court. The scope of review by a district court under section 78u(d) or (e) of this title is in all cases the same as by a court of appeals under this section."],[0,"(d) Other appropriate regulatory agencies"],[0,"(1) For purposes of the preceding subsections of this section, the term \"Commission\" includes the agencies enumerated in section 78c(a)(34) of this title insofar as such agencies are acting pursuant to this chapter and the Secretary of the Treasury insofar as he is acting pursuant to section 78o–5 of this title."],[0,"(2) For purposes of subsection (a)(4) of this section and section 706 of title 5, an order of the Commission pursuant to section 78s(a) of this title denying registration to a clearing agency for which the Commission is not the appropriate regulatory agency or pursuant to section 78s(b) of this title disapproving a proposed rule change by such a clearing agency shall be deemed to be an order of the appropriate regulatory agency for such clearing agency insofar as such order was entered by reason of a determination by such appropriate regulatory agency pursuant to section 78s(a)(2)(C) or 78s(b)(4)(C) of this title that such registration or proposed rule change would be inconsistent with the safeguarding of securities or funds."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78y?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§78y. Court review of orders and rules","tname":"Commerce and Trade","by":{"1":"16, 21"}},{"t":"usc","label":"15 U.S.C. § 766","url":"https://www.law.cornell.edu/uscode/text/15/766","subs":["(c)"],"by":{"1":"16"}},{"t":"usc","label":"15 U.S.C. § 1193","url":"https://www.law.cornell.edu/uscode/text/15/1193","subs":["(e)(1)"],"by":{"1":"16, 21"}},{"t":"usc","label":"15 U.S.C. § 2060","url":"https://www.law.cornell.edu/uscode/text/15/2060","subs":["(a)","(g)(2)"],"by":{"1":"16, 16"}},{"t":"usc","label":"15 U.S.C. § 2064","url":"https://www.law.cornell.edu/uscode/text/15/2064","by":{"1":"16, 21"}},{"t":"usc","label":"15 U.S.C. § 2618","url":"https://www.law.cornell.edu/uscode/text/15/2618","subs":["(a)(1)(A)","(a)(1)(C)(i)"],"by":{"1":"16, 16"}},{"t":"usc","label":"16 U.S.C. § 1855","url":"https://www.law.cornell.edu/uscode/text/16/1855","by":{"1":"16"}},{"t":"usc","label":"16 U.S.C. § 7704","url":"https://www.law.cornell.edu/uscode/text/16/7704","subs":["(e)(1)"],"by":{"1":"16"}},{"t":"usc","label":"30 U.S.C. § 811","url":"https://www.law.cornell.edu/uscode/text/30/811","subs":["(d)"],"by":{"1":"16"}},{"t":"usc","label":"30 U.S.C. § 1276","url":"https://www.law.cornell.edu/uscode/text/30/1276","subs":["(a)(1)"],"stext":{"head":"§1276. Judicial review","paras":[[0,"(a) Review by United States District Court; venue; filing of petition; time"],[0,"(1) Any action of the Secretary to approve or disapprove a State program or to prepare or promulgate a Federal program pursuant to this chapter shall be subject to judicial review by the United States District Court for the District which includes the capital of the State whose program is at issue. Any action by the Secretary promulgating national rules or regulations including standards pursuant to sections 1251, 1265, 1266, and 1273 of this title shall be subject to judicial review in the United States District Court for the District of Columbia Circuit. Any other action constituting rulemaking by the Secretary shall be subject to judicial review only by the United States District Court for the District in which the surface coal mining operation is located. Any action subject to judicial review under this subsection shall be affirmed unless the court concludes that such action is arbitrary, capricious, or otherwise inconsistent with law. A petition for review of any action subject to judicial review under this subsection shall be filed in the appropriate Court within sixty days from the date of such action, or after such date if the petition is based solely on grounds arising after the sixtieth day. Any such petition may be made by any person who participated in the administrative proceedings and who is aggrieved by the action of the Secretary."],[0,"(2) Any order or decision issued by the Secretary in a civil penalty proceeding or any other proceeding required to be conducted pursuant to section 554 of title 5 shall be subject to judicial review on or before 30 days from the date of such order or decision in accordance with subsection (b) of this section in the United States District Court for the district in which the surface coal mining operation is located. In the case of a proceeding to review an order or decision issued by the Secretary under the penalty section of this chapter, the court shall have jurisdiction to enter an order requiring payment of any civil penalty assessment enforced by its judgment. This availability of review established in this subsection shall not be construed to limit the operations of rights established in section 1270 of this title."],[0,"(b) Evidence; conclusiveness of findings; orders"],[0,"The court shall hear such petition or complaint solely on the record made before the Secretary. Except as provided in subsection (a), the findings of the Secretary if supported by substantial evidence on the record considered as a whole, shall be conclusive. The court may affirm, vacate, or modify any order or decision or may remand the proceedings to the Secretary for such further action as it may direct."],[0,"(c) Temporary relief; prerequisites"],[0,"In the case of a proceeding to review any order or decision issued by the Secretary under this chapter, including an order or decision issued pursuant to subsection (c) or (d) of section 1275 of this title pertaining to any order issued under paragraph (2), (3), or (4) of subsection (a) of section 1271 of this title for cessation of coal mining and reclamation operations, the court may, under such conditions as it may prescribe, grant such temporary relief as it deems appropriate pending final determination of the proceedings if—"],[1,"(1) all parties to the proceedings have been notified and given an opportunity to be heard on a request for temporary relief;"],[1,"(2) the person requesting such relief shows that there is a substantial likelihood that he will prevail on the merits of the final determination of the proceeding; and"],[1,"(3) such relief will not adversely affect the public health or safety or cause significant imminent environmental harm to land, air, or water resources."],[0,"(d) Stay of action, order, or decision of Secretary"],[0,"The commencement of a proceeding under this section shall not, unless specifically ordered by the court, operate as a stay of the action, order, or decision of the Secretary."],[0,"(e) Action of State regulatory authority"],[0,"Action of the State regulatory authority pursuant to an approved State program shall be subject to judicial review by a court of competent jurisdiction in accordance with State law, but the availability of such review shall not be construed to limit the operation of the rights established in section 1270 of this title except as provided therein."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/30/1276?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1276. Judicial review","tname":"Mineral Lands and Mining","by":{"1":"29"}},{"t":"usc","label":"33 U.S.C. § 2717","url":"https://www.law.cornell.edu/uscode/text/33/2717","subs":["(a)"],"by":{"1":"16"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 2022","url":"https://www.law.cornell.edu/uscode/text/42/2022","subs":["(c)(2)"],"by":{"1":"17"}},{"t":"usc","label":"42 U.S.C. § 5841","url":"https://www.law.cornell.edu/uscode/text/42/5841","by":{"1":"15"}},{"t":"usc","label":"42 U.S.C. § 6306","url":"https://www.law.cornell.edu/uscode/text/42/6306","subs":["(b)(1)"],"by":{"1":"17"}},{"t":"usc","label":"49 U.S.C. § 32503","url":"https://www.law.cornell.edu/uscode/text/49/32503","subs":["(a)"],"by":{"1":"17"}},{"t":"usc","label":"49 U.S.C. § 32909","url":"https://www.law.cornell.edu/uscode/text/49/32909","subs":["(b)"],"by":{"1":"17"}},{"t":"usc","label":"49 U.S.C. § 60119","url":"https://www.law.cornell.edu/uscode/text/49/60119","subs":["(a)"],"by":{"1":"17"}},{"t":"usc","label":"50 U.S.C. § 167h","url":"https://www.law.cornell.edu/uscode/text/50/167h","subs":["(b)"],"by":{"1":"15"}},{"t":"reg","label":"24 C.F.R. § 1.4","url":"https://www.ecfr.gov/current/title-24/section-1.4","by":{"1":"39"}},{"t":"reg","label":"80 Fed. Reg. 48,684","url":"https://www.govinfo.gov/link/fr/80/48684","by":{"1":"5"}},{"t":"reg","label":"86 Fed. Reg. 26,189","url":"https://www.govinfo.gov/link/fr/86/26189","by":{"1":"8"}},{"t":"reg","label":"88 Fed. Reg. 78,100","url":"https://www.govinfo.gov/link/fr/88/78100","by":{"1":"8"}},{"t":"reg","label":"38 Fed. Reg. 17,949","url":"https://www.govinfo.gov/link/fr/38/17949","by":{"1":"39"}},{"t":"reg","label":"39 Fed. Reg. 29,178","url":"https://www.govinfo.gov/link/fr/39/29178","by":{"1":"39"}},{"t":"case","label":"Adamo Wrecking Co. v. United States","cite":"434 U.S. 275","y":1978,"id":"1977/76-911","sc":1,"sum":"The Clean Air Act authorizes the Administrator of the Environmental Protection Agency (EPA) to promulgate \"emission standards\" for hazardous air pollutants. The emission of an air pollutant in violation of an applicable emission standard is prohibited by § 112 (c) (1) (B), the knowing violation of which is made a criminal offense by § 113 (c) (1) (C). Section 307 (b) (1) provides that a petition for review of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Block v. Cmty. Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Cada v. Baxter Healthcare Corp.","cite":"920 F.2d 446","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/920/446/","by":{"2":"5"}},{"t":"case","label":"Citizens for Resp. & Ethics in Washington v. NARA","cite":"2021 WL 950142","y":2021,"court":"D.D.C. Mar. 12","by":{"2":"20"}},{"t":"case","label":"CRST Van Expedited, Inc. v. EEOC","cite":"578 U.S. 419","y":2016,"id":"2015/14-1375","sc":1,"op":8,"sum":"The Court determined that a defendant may be a “prevailing party” for the purpose of the award of fees even without a ruling on the merits.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"CTIA-Wireless Ass’n v. FCC","cite":"466 F.3d 105","y":2006,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/466/105/","by":{"2":"23"}},{"t":"case","label":"Goeway v. United States","cite":"612 F.2d 539","y":1979,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/612/539/","op":1,"by":{"2":"5"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"140 S. Ct. 2367","y":2020,"id":"2019/19-431","sc":1,"op":5,"sum":"The Court held that the federal government acted properly when it added extensive exemptions to regulations requiring employers to include contraceptive coverage in employee health plans.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"op":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"142 S. Ct. 2486","y":2022,"id":"2021/21-429","sc":1,"op":1,"sum":"The Federal Government and the State have concurrent jurisdiction to prosecute crimes committed by non-Indians against Indians in Indian country.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"1"}},{"t":"case","label":"Porter v. CIA","cite":"579 F. Supp. 2d 121","y":2008,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/579/121/","by":{"2":"16"}},{"t":"case","label":"Smith v. City of Jackson, Miss.","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"U.S. Steel Corp. v. EPA","cite":"595 F.2d 207","y":1979,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/595/207/","by":{"2":"19"}},{"t":"case","label":"United States v. Lippitt","cite":"100 U.S. 663","y":1879,"id":"scdb/1879-138","sc":1,"sum":"This was a claim of Lippitt for $1,742, to which 'he alleged that he was entitled as commutation for fuel and quarters while he was in the military service of the United States. It was referred to the court below by the Department of War.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"3"}},{"t":"case","label":"WJG Tel. Co. v. FCC","cite":"675 F.2d 386","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/675/386/","by":{"2":"19"}},{"t":"case","label":"U.S.Br., Health Care Serv. Corp. v. Pollitt (No. 09- 38)","cite":"2010 WL 360215","y":2010,"court":"Feb.","by":{"2":"13"}},{"t":"case","label":"U.S.Br., Mach Mining, LLC v. EEOC (No. 13-1019)","cite":"2014 WL 5464087","y":2014,"court":"Oct.","by":{"2":"13, 14"}},{"t":"case","label":"U.S.Br., U.S. Dep’t of Army v. Blue Fox, Inc. (No. 97- 1642)","cite":"1998 WL 541980","y":1998,"court":"Aug.","by":{"2":"14"}}]};